import {EVIDENCE,REQUIRED_FIRST,REQUIRED_SECOND,AUDIT_EDGES} from './arg-content.js?v=46';
export const ARG_SAVE_KEY='qinghe_arg_save';
const norm=v=>String(v??'').normalize('NFKC').trim().toLowerCase();
export const truthy=(s,b,id)=>s[b]?.[id]?.value===true;
export const owned=(s,id)=>truthy(s,'evidence',id);
export function truth(s){const firstReady=REQUIRED_FIRST.every(id=>owned(s,id))&&owned(s,'printerRegister')&&truthy(s,'actions','imageCompared');const first=truthy(s,'actions','confronted')||truthy(s,'actions','legacyCaseResolved');const second=first&&REQUIRED_SECOND.every(id=>owned(s,id))&&['timelineChecked','medicalChecked','cacheRestored'].every(id=>truthy(s,'actions',id));const links=AUDIT_EDGES.filter(e=>truthy(s,'links',e.key)).length;return {firstReady,first,second,links,auditReady:second&&links===5&&validWorkbook(s.vault?.value)&&owned(s,'auditReview')};}
export function canRead(s,id){if(!Object.hasOwn(EVIDENCE,id))return false;const access=EVIDENCE[id].access;const t=truth(s);if(access==='vault')return validWorkbook(s.vault?.value);if(access==='audit')return t.first&&truthy(s,'accounts','shenzhi')&&truthy(s,'actions','cacheRestored');if(access==='public')return true;if(access==='first')return t.first;if(access==='clinic')return t.first&&truthy(s,'accounts','shenzhi');if(access==='card')return truthy(s,'accounts','card')&&truthy(s,'actions','cardQueried');if(access==='compared')return truthy(s,'actions','imageCompared');if(access==='springShare')return truthy(s,'accounts','spring');if(access==='auditReview')return t.second&&t.links===5&&validWorkbook(s.vault?.value);return truthy(s,'accounts',access);}
export function freshArgState(){return {version:3,clock:0,discovered_sites:['forum'],evidence:{},deductions:{},accounts:{},actions:{},links:{},prefs:{},notes:{},marks:{},vault:null};}
const buckets=['evidence','deductions','accounts','actions','links','prefs','notes','marks'];
const accountIDs=new Set(['jie','yida','azhe','shenzhi','card','spring','relay','makeup']);
const actionIDs=new Set(['imageCompared','confronted','legacyCaseResolved','timelineChecked','medicalChecked','cacheRestored','cardQueried','endingA','endingB','caseReconstructed']);
function validEntry(e){return e&&Number.isSafeInteger(e.tick)&&e.tick>=0&&typeof e.actor==='string'&&e.actor.length<=90;}
export function validWorkbook(w){return !!w&&Array.isArray(w.columns)&&w.columns.length===5&&w.columns.every(x=>typeof x==='string'&&x.length<150)&&Array.isArray(w.rows)&&w.rows.length>0&&w.rows.length<=20&&w.rows.every(r=>Array.isArray(r)&&r.length===5&&r.every(v=>typeof v==='string'&&v.length<300))&&typeof w.xlsx==='string'&&w.xlsx.length<30000&&/^[A-Za-z0-9+/=]+$/.test(w.xlsx);}
export function sanitizeArgState(raw){let x;try{x=typeof raw==='string'?JSON.parse(raw):raw;}catch{return freshArgState();}if(x?.version!==3)return freshArgState();const s=freshArgState();s.clock=Number.isSafeInteger(x.clock)?Math.max(0,x.clock):0;
 for(const b of buckets)for(const [id,e]of Object.entries(x[b]||{}).slice(0,250)){if(!validEntry(e)||['__proto__','constructor','prototype'].includes(id))continue;let value=e.value;if(b==='deductions'&&!DEDUCTIONS.some(d=>d.id===id)||b==='evidence'&&!Object.hasOwn(EVIDENCE,id)||b==='accounts'&&!accountIDs.has(id)||b==='actions'&&!actionIDs.has(id)||b==='links'&&!AUDIT_EDGES.some(k=>k.key===id))continue;if(['evidence','deductions','accounts','actions','links'].includes(b)&&typeof value!=='boolean')continue;if(b==='notes'&&(id!=='personal'||typeof value!=='string'))continue;if(b==='notes')value=value.slice(0,4000);if(b==='prefs'&&(id!=='sound'||typeof value!=='boolean'))continue;if(b==='marks'){if(!/^[a-z-]{1,30}$/.test(id)||!Array.isArray(value))continue;value=value.filter(v=>typeof v==='string'&&v.length<70).slice(0,40);}s[b][id]={value,tick:e.tick,actor:e.actor};s.clock=Math.max(s.clock,e.tick);}
 s.discovered_sites=normalizeSites(x.discovered_sites);
 if(!Array.isArray(x.discovered_sites)){for(const id of Object.keys(s.evidence))if(owned(s,id))s.discovered_sites=normalizeSites([...s.discovered_sites,EVIDENCE[id]?.site]);if(s.accounts.card?.value)s.discovered_sites=normalizeSites([...s.discovered_sites,'canteen']);if(['jie','yida','azhe','shenzhi','spring','relay','makeup'].some(id=>s.accounts[id]?.value))s.discovered_sites=normalizeSites([...s.discovered_sites,'pan']);if(Object.keys(s.marks).some(id=>id.startsWith('clip-')))s.discovered_sites=normalizeSites([...s.discovered_sites,'video']);}
 if(validEntry(x.vault)&&validWorkbook(x.vault.value))s.vault={value:normalizeSavedWorkbook(x.vault.value),tick:x.vault.tick,actor:x.vault.actor};for(const d of DEDUCTIONS)if(s.deductions[d.id]&&!deductionReady(s,d))delete s.deductions[d.id];return s;
}
const stable=v=>JSON.stringify(v,(_key,value)=>value&&typeof value==='object'&&!Array.isArray(value)?Object.fromEntries(Object.keys(value).sort().map(k=>[k,value[k]])):value);
export const sameState=(a,b)=>stable(a)===stable(b);
function newer(a,b){if(!a)return b;if(!b)return a;return a.tick!==b.tick?(a.tick>b.tick?a:b):a.actor!==b.actor?(a.actor>b.actor?a:b):stable(a.value)>=stable(b.value)?a:b;}
export function mergeArgStates(a,b){a=sanitizeArgState(a);b=sanitizeArgState(b);const out=freshArgState();out.clock=Math.max(a.clock,b.clock);for(const bucket of buckets)for(const key of [...new Set([...Object.keys(a[bucket]),...Object.keys(b[bucket])])].sort())out[bucket][key]=newer(a[bucket][key],b[bucket][key]);out.vault=newer(a.vault,b.vault);out.discovered_sites=normalizeSites([...a.discovered_sites,...b.discovered_sites]);return out;}
export function stampValue(s,b,id,value,stamp){s[b][id]={value,tick:stamp.tick,actor:stamp.actor};s.clock=Math.max(s.clock,stamp.tick);}
export function act(s,type,p={},stamp={tick:s.clock+1,actor:'local'}){const set=(b,id,value=true)=>stampValue(s,b,id,value,stamp),ok=message=>({ok:true,message}),no=message=>({ok:false,message});
 if(type==='discover'){if(!SITE_IDS.includes(p.site))return no('没有对应的站点。');if(s.discovered_sites.includes(p.site))return ok('已在调查书签中。');s.discovered_sites=normalizeSites([...s.discovered_sites,p.site]);s.clock=Math.max(s.clock,stamp.tick);return ok('已将【'+SITE_NAMES[p.site]+'】添加至调查书签');}
 if(type==='synthesize'){const d=matchDeduction(p.pair);if(!d||!d.pair.every(id=>owned(s,id)))return no('这两条信息暂时看不出直接矛盾');if(!deductionReady(s,d)||d.vault&&!validWorkbook(s.vault?.value))return no(d.missing);if(truthy(s,'deductions',d.id))return ok('这条推论已经记下，原始材料仍可重读。');set('deductions',d.id);return ok('核心推论已记下：'+d.title);}
 if(type==='collect'){if(!canRead(s,p.id))return no('这份资料还没有获得阅览授权。');if(owned(s,p.id))return ok('已在调查本中。');set('evidence',p.id);return ok('已记下：'+EVIDENCE[p.id].title);}
 if(type==='login'){if(p.account==='azhe'&&norm(p.password)==='0323')return no('需补充校刊英文缩写，并核对当周期号。');const passwords={jie:'1264',yida:'b1018',azhe:'hs032316',card:'1264',makeup:'03281430'};if(!Object.hasOwn(passwords,p.account)||norm(p.password)!==passwords[p.account]||p.account==='card'&&norm(p.student)!=='20220327')return no('账号或口令没有对上，回看对方给的两份材料。');set('accounts',p.account);return ok('授权资料已开放。');}
 if(type==='recover'){if(!truth(s).first)return no('这份授权还没有交到你手里。');if(!['authorization','oldpost','radio'].every(id=>owned(s,id)))return no('先核对授权、首次值班旧帖和对应广播排期。');if(norm(p.song)!=='夜空中最亮的星')return no('同是周五末曲，也要对应第一次值班的日期。');set('accounts','shenzhi');return ok('小范的只读副本已解锁。');}
 if(type==='share'){if(p.folder==='spring'&&norm(p.code)==='0314xsh'||p.folder==='relay'&&norm(p.code)==='1018b'){set('accounts',p.folder);return ok('源素材目录已打开。');}return no('提取码没有匹配，核对拍摄日、地点或机位，不用上传日期。');}
 if(type==='card'){if(!truthy(s,'accounts','card'))return no('请先登录授权的学生查询。');if(![p.from,p.to].every(v=>/^2025-\d{2}-\d{2}$/.test(v||'')&&!Number.isNaN(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v)||p.from>p.to)return no('日期范围无效。');if(p.from<='2025-03-13'&&p.to>='2025-03-13')set('actions','cardQueried');return ok('查询完成。');}
 if(type==='compare'){if(!['reportBy','reportUnknown','submission'].every(id=>owned(s,id)))return no('还缺能排除发帖时选错附件的原始收稿。');if(p.marks?.includes('stamp'))return no('盖章角度会批量重复，不能唯一识别同一张纸。');if(p.marks?.includes('noise'))return no('灰点可能来自扫描底版或打印设备，不能唯一认纸。');if(!Array.isArray(p.marks)||p.marks.length!==2||!['fold','circle'].every(x=>p.marks.includes(x)))return no('需要核对纸张使用后留下、能在同一位置对齐的细节。');set('actions','imageCompared');set('evidence','sameImage');return ok('A与C来自同一张原图，C不能独立计为另一位患者。');}
 if(type==='confront'){if(!truth(s).firstReady)return no('还不能只凭远景或一句弹幕认定改图。需要原始投稿、原图接触和请假说法相互印证。');set('actions','confronted');return ok('朱贵愿意把这件事说清楚了。');}
 if(type==='timeline'){if(!owned(s,'clockNote'))return no('还需核对水房维修回帖里的同机号校时说明，屏显与导出不是同一时间基准。');if(!owned(s,'screenMemory'))return no('还缺当事人原话。回看就医经历主帖里杰哥记得的屏显，别用转述代替。');if(!truth(s).first||!['roster','swipe','attendance','signoff'].every(id=>owned(s,id)))return no('需要名册、流水、点名和本人签收四份来源。');if(p.roster!=='m4'||p.swipe!=='s3'||p.attendance!=='a2'||p.signoff!=='r2'||p.explanation!=='proxy'||!/^20:?41$/.test(norm(p.normalized))||p.correction!=='export-corrected')return no('核对屏显换算、导出是否已校正，以及同日有效流水、卡号前缀和本人签收。批准的夜宵与走读离校不是缺勤。');set('actions','timelineChecked');return ok('“全程在场”与本人签收不符，点名为事后誊录。');}
 if(type==='medical'){if(!['medical','medication','summary'].every(id=>owned(s,id)))return no('先把复查送达、用药和汇总放在一起。');if(p.patient!=='R07'||norm(p.repeat)!=='0329'||p.interpretation!=='unreliable'||p.batch!=='unknown')return no('检查的是初检可靠性和已收材料是否漏列。DOB和症状顺序不能反推传播批次。');set('actions','medicalChecked');return ok('R07准备不足的初检不能直接排除；多份复查送达早于“无新增”汇总。传播来源仍未知。');}
 if(type==='restore'){if(!truthy(s,'accounts','shenzhi')||!owned(s,'cache'))return no('需要授权的本地草稿缓存。');if(p.fragments?.join(',')!=='d2-head,d2-tail')return no('请核对草稿编号、修订号和首尾段，不能把旧尾段接进新版本。');set('actions','cacheRestored');return ok('D0329修订02已恢复，保留原文和版本出处。');}
 if(type==='vault'){if(!truth(s).first||!truthy(s,'actions','cacheRestored')||!owned(s,'blackboard')||!validWorkbook(p.payload))return no('需要草稿中的附件出处、黑板报和已实际解密的工作表。');s.vault={value:p.payload,...stamp};set('evidence','ledger');return ok('原导出包验证成功，工作表已经载入。');}
 if(type==='link'){const edge=AUDIT_EDGES.find(e=>e.relation===p.relation&&(e.from===p.from&&e.to===p.to||e.relation==='contradicts'&&e.from===p.to&&e.to===p.from));if(!edge||!owned(s,p.from)||!owned(s,p.to))return no('这两张卡还不能支持这种关系，注意改写和结算有方向。');if(edge.from==='attendance'&&!truthy(s,'actions','timelineChecked')||edge.from==='summary'&&!truthy(s,'actions','medicalChecked')||edge.from==='ledger'&&!validWorkbook(s.vault?.value)||['lab-original','contract'].includes(edge.from)&&!truthy(s,'actions','cacheRestored'))return no('这组来源还缺独立核对，回看原件旁的质疑记录。');set('links',edge.key);return ok(edge.label);}
 if(type==='unlink'){if(!AUDIT_EDGES.some(e=>e.key===p.key))return no('没有这组关系。');set('links',p.key,false);return ok('已移除，原始材料仍保留。');}
 if(type==='reconstruct'){if(!truth(s).auditReady||!owned(s,'clockNote')||!truthy(s,'deductions','memory-clock'))return no('复盘还缺原件复核、五组审计关系或屏显记忆纠偏，先把材料核实。');if(!correctReconstruction(p))return no('这条真相链还有一环对不上。请对原件核对时间基准、设备与改写内容，别用猜测补空。');if(truthy(s,'actions','caseReconstructed'))return ok('复盘已核实，完整档案仍可重读。');set('actions','caseReconstructed');return ok('真相链已还原，完整真相档案与后续已收进调查本。');}
 if(type==='ending'){if(p.choice==='A'&&truth(s).first&&owned(s,'summary')){set('actions','endingA');return ok('先按现有通报处理，材料保留，仍可继续补证。');}if(p.choice==='B'&&truth(s).auditReady){if(!truthy(s,'actions','caseReconstructed')&&!truthy(s,'actions','endingB'))return no('材料已齐，还要在调查本里完成“还原真相链”，再提交完整说明。');set('actions','endingB');return ok('完整材料与复核回函已提交公开整改。');}return no('公开整改需要五组核心互证和原件复核，现有材料不会被清空。');}
 if(type==='note'&&typeof p.text==='string'){set('notes','personal',p.text.slice(0,4000));return ok('手记已保存。');}if(type==='sound'){set('prefs','sound',p.on===true);return ok(p.on?'提示音已开启。':'提示音已关闭。');}if(type==='mark'&&/^[a-z-]{1,30}$/.test(p.table)){set('marks',p.table,(p.rows||[]).slice(0,40));return ok('已标记。');}return no('这项操作没有对应的调查记录。');
}
export function migrateLegacy(raw){let x;try{x=typeof raw==='string'?JSON.parse(raw):raw;}catch{return freshArgState();}const s=freshArgState();if(x?.version!==1)return s;x=parseOldSave(JSON.stringify(x));const stamp={tick:1,actor:'legacy-migration'},set=(b,id,value=true)=>stampValue(s,b,id,value,stamp);for(const id of [...(x.clues||[]),...(x.expansion?.evidence||[])])if(Object.hasOwn(EVIDENCE,id))set('evidence',id);if(x.caseSolved===true&&x.caseStage===8){set('actions','legacyCaseResolved');set('actions','imageCompared');}if(['jie','yida','azhe'].includes(x.activeAccount))set('accounts',x.activeAccount);if(x.expansion?.recovered)set('accounts','shenzhi');for(const [old,id]of [['timeline','timelineChecked'],['medical','medicalChecked'],['cache','cacheRestored']])if(x.expansion?.solved?.includes(old))set('actions',id);if(x.expansion?.restored)set('actions','cacheRestored');if(x.expansion?.visitedEndings?.includes('A'))set('actions','endingA');if(x.expansion?.stage===6&&x.expansion?.visitedEndings?.includes('B'))set('actions','endingB');if(validWorkbook(x.expansion?.workbook))s.vault={value:x.expansion.workbook,...stamp};for(const key of x.expansion?.links||[])if(AUDIT_EDGES.some(e=>e.key===key))set('links',key);for(const id of x.savedDocs||[]){const ev=Object.keys(EVIDENCE).find(k=>EVIDENCE[k].sourceDoc===id);if(ev)set('evidence',ev);}if((x.savedDocs||[]).includes('receipt')){set('evidence','receipt');set('accounts','card');set('actions','cardQueried');}delete s.discovered_sites;return sanitizeArgState(s);}
export function siteURL(site,params={},from='forum'){const path=(from==='forum'?'':'../')+(site==='forum'?'index.html':site+'/index.html');const q=new URLSearchParams(params).toString();return path+(q?'?'+q:'');}
export const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
